		public void TestLinkBackToReconDeclaration()
		{
			var reconDeclaration = new DeclarationTestHelper().GetDutiableReconDeclaration(Factory);
			reconDeclaration.InvoiceLines[0].JI_Tariff = "1111111111";
			Factory.Save();
			AssertEquals("Should have requested for one tariff", 1, reconDeclaration.Messages.Count);
			reconDeclaration.Messages[0].EM_MessageNum = "~8862";

			var mock = Factory.NewMoq<MQEDIMessage>();
			mock.Protected().Setup("GetNumberFountainNumbersAndFillInPlaceHolders");

			var messageResponse = mock.Object;
			messageResponse.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			messageResponse.EM_MessageType = ApplicationIdentifierCodeList.Codes.QueryHarmonizedSystem;
			messageResponse.EM_ReceiveTransmit = EDIMessage.Direction.Receive;
			messageResponse.EM_MessageNum = "~8862";
			messageResponse.EM_MessageText =
				"B018888XJ5WR                                               ~8862                " +
				"W16206900040 0101091231092DOZKG    7W/G BLOUSES,OF TEXT MAT, OTHER000000000000  " +
				"W26206900040000006700000000000000000000000000000000090000000000000000000        " +
				"W36206900040                                    1840E*P AUBHCACLILJOMAMXSG      " +
				"W56206900040AU00000000000000000600000000000000000005621000000245900000000000000 " +
				"W66206900040MA000000000000000001300000000000000000                              " +
				"Y  8888XJ5WR00007";

			Factory.Save();

			new USRIncomingMessageProcessor().ExecuteBatch();

			Factory.Save();

			var factory = new BusinessObjectFactory();
			var reconDecLoaded = new ReconDeclaration(factory.Load<JobDeclaration>(reconDeclaration.JE_PK));
			AssertEquals("the response is attached to reconDec OK", 2, reconDecLoaded.Messages.Count);
		}

		public void TestProcessTariffDeleteOtherValueAndQuantity()
		{
			var tariffToBeUpdated = Factory.New<USCTariff>();
			tariffToBeUpdated.UE_Tariff = "640291709A";
			tariffToBeUpdated.UE_DateFrom = new ZDateTime(2012, 10, 31);
			tariffToBeUpdated.UE_DateTo = new ZDateTime(2099, 12, 31);
			tariffToBeUpdated.UE_ShortDescription = "TARIFF 1";
			var value1 = Factory.New<USCTariffValue>();
			value1.UA_UE = tariffToBeUpdated.PK;
			value1.UA_ValueEditCode = "A";
			var value2 = Factory.New<USCTariffValue>();
			value2.UA_UE = tariffToBeUpdated.PK;
			value2.UA_ValueEditCode = "A";
			var quantity1 = Factory.New<USCTariffQuantity>();
			quantity1.UQ_UE = tariffToBeUpdated.PK;
			quantity1.UQ_QuantityEditCode = "A";
			var quantity2 = Factory.New<USCTariffQuantity>();
			quantity2.UQ_UE = tariffToBeUpdated.PK;
			quantity2.UQ_QuantityEditCode = "A";
			var messageResponse1 = Factory.New<MQEDIMessage>();
			messageResponse1.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			messageResponse1.EM_MessageType = ApplicationIdentifierCodeList.Codes.ExtractReferenceFilesResponse;
			messageResponse1.EM_ReceiveTransmit = EDIMessage.Direction.Receive;
			messageResponse1.EM_MessageNum = "25258";
			messageResponse1.EM_MessageText =
				"B018888XJ5FR                                               25258                " +
				"F1109805                                                                        " +
				"V1640291709AR1031129999991PRS      4FTWR,O PER,C AN,OV$3,N/O$6    000090000000  " +
				"V2640291709A000037500000000000000000000158000000000066000000000000000000        " +
				"V3640291709A                                        D E R P AUBHCACLCOILJ+JOKRMA" +
				"V4640291709A11100003000000000650000                      22200004000000000750000" +
				"V5640291709ASG000009000000000003700000000000000000                              " +
				"VD640291709AMXOMPAPESG                                                          " +
				"Y  8888XJ5FR00815";

			Factory.Save();
			new USRIncomingMessageProcessor().ExecuteBatch();

			var newFactory = new BusinessObjectFactory();
			tariffToBeUpdated = newFactory.Load<USCTariff>(tariffToBeUpdated.PK);
			AssertTariff(tariffToBeUpdated, "640291709A", new ZDateTime(2012, 10, 31), new ZDateTime(2099, 12, 31));
			var tariffValues = newFactory.Load<USCTariffValue>(new ZQuery(USCTariffValueSchema.UA_UE, tariffToBeUpdated.PK));
			AssertEquals(1, tariffValues.Length);
			var deletedValue = value1;
			var value = value2;
			if (tariffValues[0].PK == value1.PK)
			{
				deletedValue = value2;
				value = value1;
			}
			AssertNotNull(newFactory.Load<USCTariffValue>(value.PK));
			AssertNull(newFactory.Load<USCTariffValue>(deletedValue.PK));
			var tariffQuantities = newFactory.Load<USCTariffQuantity>(new ZQuery(USCTariffQuantitySchema.UQ_UE, tariffToBeUpdated.PK));
			AssertEquals(1, tariffQuantities.Length);
			var deletedQuantity = quantity1;
			var quantity = quantity2;
			if (tariffQuantities[0].PK == quantity1.PK)
			{
				deletedQuantity = quantity2;
				quantity = quantity1;
			}
			AssertNotNull(newFactory.Load<USCTariffQuantity>(quantity.PK));
			AssertNull(newFactory.Load<USCTariffQuantity>(deletedQuantity.PK));
		}

		public void TestProcessTariffDeleteOverlapingTariffIfNeeded()
		{
			var tariffToBeUpdated = Factory.New<USCTariff>();
			tariffToBeUpdated.UE_Tariff = "640291709A";
			tariffToBeUpdated.UE_DateFrom = new ZDateTime(2012, 1, 1);
			tariffToBeUpdated.UE_DateTo = new ZDateTime(2012, 12, 1);
			tariffToBeUpdated.UE_ShortDescription = "TARIFF 1";
			var overlappingTariffThatNeedsToBeDeleted = Factory.New<USCTariff>();
			overlappingTariffThatNeedsToBeDeleted.UE_Tariff = "640291709A";
			overlappingTariffThatNeedsToBeDeleted.UE_DateFrom = new ZDateTime(2012, 11, 1);
			overlappingTariffThatNeedsToBeDeleted.UE_DateTo = new ZDateTime(2013, 1, 1);
			overlappingTariffThatNeedsToBeDeleted.UE_ShortDescription = "TARIFF 2";

			var messageResponse1 = Factory.New<MQEDIMessage>();
			messageResponse1.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			messageResponse1.EM_MessageType = ApplicationIdentifierCodeList.Codes.ExtractReferenceFilesResponse;
			messageResponse1.EM_ReceiveTransmit = EDIMessage.Direction.Receive;
			messageResponse1.EM_MessageNum = "25258";
			messageResponse1.EM_MessageText =
				"B018888XJ5FR                                               25258                " +
				"F1109805                                                                        " +
				"V1640291709AR1031129999991PRS      4FTWR,O PER,C AN,OV$3,N/O$6    000090000000  " +
				"V2640291709A000037500000000000000000000158000000000066000000000000000000        " +
				"V3640291709A                                        D E R P AUBHCACLCOILJ+JOKRMA" +
				"V4640291709A11100003000000000650000                                             " +
				"V5640291709ASG000009000000000003700000000000000000                              " +
				"VD640291709AMXOMPAPESG                                                          " +
				"V1640291709AA0101131231131PRS      4FTWR,O PER,C AN,OV$3,N/O$6    000090000000  " +
				"V2640291709A000037500000000000000000000158000000000066000000000000000000        " +
				"V3640291709A                                        D E R P AUBHCACLCOILJ+JOKRMA" +
				"V4640291709A11100003000000000650000                                             " +
				"VD640291709AMXOMPAPESG                                                          " +
				"Y  8888XJ5FR00815";

			Factory.Save();
			new USRIncomingMessageProcessor().ExecuteBatch();

			var newFactory = new BusinessObjectFactory();
			tariffToBeUpdated = newFactory.Load<USCTariff>(tariffToBeUpdated.PK);
			AssertTariff(tariffToBeUpdated, "640291709A", new ZDateTime(2012, 1, 1), new ZDateTime(2012, 10, 30));
			AssertNull("Has been deleted", newFactory.Load<USCTariff>(overlappingTariffThatNeedsToBeDeleted.PK));
			var query = new ZQuery(USCTariffSchema.UE_Tariff, "640291709A");
			query.AddToFilter(USCTariffSchema.UE_DateFrom, new ZDateTime(2012, 10, 31));
			query.AddToFilter(USCTariffSchema.UE_DateTo, new ZDateTime(2012, 12, 31));
			var newTariffAdded1 = newFactory.LoadTop1<USCTariff>(query);
			AssertNotNull(newTariffAdded1);
			query = new ZQuery(USCTariffSchema.UE_Tariff, "640291709A");
			query.AddToFilter(USCTariffSchema.UE_DateFrom, new ZDateTime(2013, 1, 1));
			query.AddToFilter(USCTariffSchema.UE_DateTo, new ZDateTime(2013, 12, 31));
			var newTariffAdded2 = newFactory.LoadTop1<USCTariff>(query);
			AssertNotNull(newTariffAdded2);

			var messageResponse2 = Factory.New<MQEDIMessage>();
			messageResponse2.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			messageResponse2.EM_MessageType = ApplicationIdentifierCodeList.Codes.ExtractReferenceFilesResponse;
			messageResponse2.EM_ReceiveTransmit = EDIMessage.Direction.Receive;
			messageResponse2.EM_MessageNum = "25258";
			messageResponse2.EM_MessageText =
				"B018888XJ5FR                                               25258                " +
				"F1109805                                                                        " +
				"V1640291709AR1031121231121PRS      4FTWR,O PER,C AN,OV$3,N/O$6    000090000000  " +
				"V2640291709A000037500000000000000000000158000000000066000000000000000000        " +
				"V3640291709A                                        D E R P AUBHCACLCOILJ+JOKRMA" +
				"V4640291709A11100003000000000650000                                             " +
				"V5640291709ASG000009000000000003700000000000000000                              " +
				"VD640291709AMXOMPAPESG                                                          " +
				"V1640291709AR0101139999991PRS      4FTWR,O PER,C AN,OV$3,N/O$6    000090000000  " +
				"V2640291709A000037500000000000000000000158000000000066000000000000000000        " +
				"V3640291709A                                        D E R P AUBHCACLCOILJ+JOKRMA" +
				"V4640291709A11100003000000000650000                                             " +
				"V5640291709ASG000009000000000003700000000000000000                              " +
				"VD6402917090MXOMPAPESG                                                          " +
				"Y  8888XJ5FR00815";

			Factory.Save();
			new USRIncomingMessageProcessor().ExecuteBatch();

			newFactory = new BusinessObjectFactory();
			tariffToBeUpdated = newFactory.Load<USCTariff>(tariffToBeUpdated.PK);
			AssertTariff(tariffToBeUpdated, "640291709A", new ZDateTime(2012, 1, 1), new ZDateTime(2012, 10, 30));
			newTariffAdded1 = newFactory.Load<USCTariff>(newTariffAdded1.PK);
			AssertTariff(newTariffAdded1, "640291709A", new ZDateTime(2012, 10, 31), new ZDateTime(2012, 12, 31));
			AssertNull("Has been deleted", newFactory.Load<USCTariff>(newTariffAdded2.PK));
			query = new ZQuery(USCTariffSchema.UE_Tariff, "640291709A");
			query.AddToFilter(USCTariffSchema.UE_DateFrom, new ZDateTime(2013, 1, 1));
			query.AddToFilter(USCTariffSchema.UE_DateTo, new ZDateTime(2099, 12, 31));
			var newTariffAdded3 = newFactory.LoadTop1<USCTariff>(query);
			AssertNotNull(newTariffAdded3);
		}

		void AssertTariff(USCTariff tariff, ZString tariffNum, ZDateTime dateFrom, ZDateTime dateTo)
		{
			AssertEquals("TariffNum", tariffNum, tariff.UE_Tariff);
			AssertEquals("DateFrom", dateFrom, tariff.UE_DateFrom);
			AssertEquals("DateTo", dateTo, tariff.UE_DateTo);
		}

		public void TestResetVersion()
		{
			var query = new ZQuery(EDIMessageSchema.EM_MessageType, ApplicationIdentifierCodeList.Codes.ExtractReferenceFiles);
			AssertEquals("Precodition: no FI messages in EDIMessage table", 0, Factory.Load<EDIMessage>(query).Length);

			var mock = Factory.NewMoq<MQEDIMessage>();
			mock.Protected().Setup("GetNumberFountainNumbersAndFillInPlaceHolders");
			var messageOutgoing = mock.Object;
			messageOutgoing.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			messageOutgoing.EM_MessageType = ApplicationIdentifierCodeList.Codes.ExtractReferenceFiles;
			messageOutgoing.EM_ReceiveTransmit = EDIMessage.Direction.Transmit;
			messageOutgoing.EM_Status = EDIMessage.Status.Sent;
			messageOutgoing.EM_MessageNum = "25258";

			var lastHTSAttempt = USCDataVersion.GetLastHTSAttempt(Factory);
			lastHTSAttempt.SetNoteWithDatabaseDetail(ExtractReferenceFilesResult.Success);
			lastHTSAttempt.UZ_Version = 9805;

			var messageResponse = Factory.New<MQEDIMessage>();
			messageResponse.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			messageResponse.EM_MessageType = ApplicationIdentifierCodeList.Codes.ExtractReferenceFilesResponse;
			messageResponse.EM_ReceiveTransmit = EDIMessage.Direction.Receive;
			messageResponse.EM_MessageNum = "25258";
			messageResponse.EM_MessageText =
				"B018888XJ5FR                                               25258                " +
				"F1109805                                                                        " +
				"V10202105010R0915061231061KG       7VEAL CARCASSES/HALF,FROZEN    000000000000  " +
				"V20202105010000026400000000000000000000000000000000031100000000000000000        " +
				"V30202105010                                    1   P AUBHCACLJOMAMXP+SG        " +
				"V50202105010AU00000000000099999999999900000000000005311000001459542000000000000 " +
				"V60202105010BH000000000000999999999999000000000000                              " +
				"V70202105010CL000000000000999999999999000000000000                              " +
				"V80202105010JO000000000000000010500000000000000000                              " +
				"V90202105010MA000000000000999999999999000000000000                              " +
				"VA0202105010P 000000000000000024600000000000000000                              " +
				"VB0202105010P+000000000000999999999999000000000000                              " +
				"VC0202105010SG000000000000999999999999000000000000                              " +
				"Y  8888XJ5FR00815";

			Factory.Save();

			new USRIncomingMessageProcessor().ExecuteBatch();

			lastHTSAttempt.Reload();

			AssertEquals(ExtractReferenceFilesResult.Pending + "," + USCDataVersion.Constant.DatabaseNameIdentifier + Db.DatabaseName, lastHTSAttempt.UZ_Note);
			AssertEquals(9806, lastHTSAttempt.UZ_Version);
			AssertEquals("FI messages should be sent", 2, Factory.Load<EDIMessage>(query).Length);

			var mock2 = Factory.NewMoq<MQEDIMessage>();
			mock2.Protected().Setup("GetNumberFountainNumbersAndFillInPlaceHolders");
			var messageOutgoing2 = mock2.Object;
			messageOutgoing2.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			messageOutgoing2.EM_MessageType = ApplicationIdentifierCodeList.Codes.ExtractReferenceFiles;
			messageOutgoing2.EM_ReceiveTransmit = EDIMessage.Direction.Transmit;
			messageOutgoing2.EM_MessageNum = "482";

			var messageResponse2 = Factory.New<MQEDIMessage>();
			messageResponse2.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			messageResponse2.EM_MessageType = ApplicationIdentifierCodeList.Codes.ExtractReferenceFilesResponse;
			messageResponse2.EM_ReceiveTransmit = EDIMessage.Direction.Receive;
			messageResponse2.EM_MessageNum = "482";
			messageResponse2.EM_MessageText =
				"B018888XJ5FR                                               482                  " +
				"F1109806                    NO UPDATES FOUND IN THIS RANGE                      " +
				"Y  8888XJ5FR00001";

			Factory.Save();

			new USRIncomingMessageProcessor().ExecuteBatch();

			lastHTSAttempt.Reload();

			AssertEquals(ExtractReferenceFilesResult.Pending + "," + USCDataVersion.Constant.DatabaseNameIdentifier + Db.DatabaseName, lastHTSAttempt.UZ_Note);
			AssertEquals("next year attempt", 9901, lastHTSAttempt.UZ_Version);
			AssertEquals("additional FI messages should be sent", 4, Factory.Load<EDIMessage>(query).Length);
		}

