		public void TestPGAIndicatorsAddedToOGA()
		{
			var tariffToBeUpdated = Factory.New<USCTariff>();
			tariffToBeUpdated.UE_Tariff = "020210501F";
			tariffToBeUpdated.UE_DateFrom = ZDateTime.Today.AddYears(-2);
			tariffToBeUpdated.UE_DateTo = ZDateTime.Today.AddYears(2);
			tariffToBeUpdated.UE_OGACodes = "EP2EP4FS4";

